// Example of how to use NavigationService and NavigationMixin in other screens\n// This demonstrates the usage pattern for any new screen\n\nimport 'package:flutter/material.dart';\nimport 'package:tailer_app/core/services/navigation_service.dart';\nimport 'package:tailer_app/core/mixins/navigation_mixin.dart';\nimport 'package:tailer_app/widgets/custom_bottom_navigation.dart';\n\n/// Example screen showing how to use common navigation\nclass ExampleScreen extends StatefulWidget {\n  const ExampleScreen({Key? key}) : super(key: key);\n\n  @override\n  State<ExampleScreen> createState() => _ExampleScreenState();\n}\n\n/// State class with NavigationMixin for easy navigation\nclass _ExampleScreenState extends State<ExampleScreen> with NavigationMixin {\n  int _currentNavIndex = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Example Screen')),\n      body: Column(\n        children: [\n          // Example buttons using mixin methods\n          ElevatedButton(\n            onPressed: () => navigateToDashboard(context),\n            child: const Text('Go to Dashboard'),\n          ),\n          ElevatedButton(\n            onPressed: () => navigateToCustomers(context),\n            child: const Text('Go to Customers'),\n          ),\n          ElevatedButton(\n            onPressed: () => navigateToCustomerProfile(context),\n            child: const Text('Go to Customer Profile'),\n          ),\n          \n          // Example using NavigationService directly\n          ElevatedButton(\n            onPressed: () => NavigationService.navigateToDestination(\n              context,\n              'Custom Destination',\n              route: '/custom-route',\n            ),\n            child: const Text('Custom Navigation'),\n          ),\n          \n          // Example showing message only\n          ElevatedButton(\n            onPressed: () => showNavigationMessage(\n              context,\n              'Feature Coming Soon',\n              customMessage: 'This feature will be available in the next update!',\n            ),\n            child: const Text('Show Message'),\n          ),\n        ],\n      ),\n      bottomNavigationBar: AnimatedBottomNavigation(\n        currentIndex: _currentNavIndex,\n        onTap: _onNavTap,\n        items: TailorAppBottomNavItems.defaultItems,\n      ),\n    );\n  }\n\n  /// Bottom navigation using mixin - same pattern for all screens\n  void _onNavTap(int index) {\n    handleBottomNavigation(\n      context,\n      index,\n      _currentNavIndex,\n      (newIndex) => setState(() => _currentNavIndex = newIndex),\n      // Optional: customize routes and destinations per screen\n      customRoutes: [\n        NavigationRoutes.dashboard,\n        NavigationRoutes.customers,\n        null, // Orders not implemented\n        null, // Settings not implemented\n      ],\n    );\n  }\n}\n\n/// Alternative approach: Using NavigationService directly without mixin\nclass ExampleScreenWithoutMixin extends StatefulWidget {\n  const ExampleScreenWithoutMixin({Key? key}) : super(key: key);\n\n  @override\n  State<ExampleScreenWithoutMixin> createState() => _ExampleScreenWithoutMixinState();\n}\n\nclass _ExampleScreenWithoutMixinState extends State<ExampleScreenWithoutMixin> {\n  int _currentNavIndex = 0;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Example Without Mixin')),\n      body: Column(\n        children: [\n          ElevatedButton(\n            onPressed: () => NavigationService.navigateToDestination(\n              context,\n              NavigationDestinations.dashboard,\n              route: NavigationRoutes.dashboard,\n            ),\n            child: const Text('Go to Dashboard'),\n          ),\n        ],\n      ),\n      bottomNavigationBar: AnimatedBottomNavigation(\n        currentIndex: _currentNavIndex,\n        onTap: _onNavTap,\n        items: TailorAppBottomNavItems.defaultItems,\n      ),\n    );\n  }\n\n  void _onNavTap(int index) {\n    NavigationService.handleBottomNavigation(\n      context,\n      index,\n      _currentNavIndex,\n      (newIndex) => setState(() => _currentNavIndex = newIndex),\n    );\n  }\n}